/// <summary>
/// CB167_PerformStockReservation
/// This class <c>METStockReservation</c> contains the logic to reserve stocks.
/// </summary>
class METStockReservation
{
    SalesTable        salesTable;
    METCustParameters metCustParameters;
    CustGroupId       custGroupId;
    boolean           lineSubstituted;
    METSalesOrderExtractionId extractionId;

    //CB238 - xDock
    InventParameters inventParameter;
    boolean isCrossDockOrCSDOrder;
    boolean isTOReceived;
    boolean isIntercompanyTransferFulfillment;
    int     batchTransactionCommit;
    METProcMetrics procMetrics;

}

Method.Source:
/// <summary>
/// Gets/sets Salestable.
/// </summary>
/// <param name = "_salesTable">Salestable.</param>
/// <returns>Salestable.</returns>
public SalesTable parmSalesTable(SalesTable _salesTable = salesTable)
{
    salesTable = _salesTable;
    return salesTable;
}

/// <summary>
/// Gets Customer group.
/// </summary>
/// <returns>Customer group.</returns>
private CustGroupId getCustGroupId()
{
    if (!custGroupId)
    {
        custGroupId = salesTable.custTable_CustAccount().CustGroup;
    }

    return custGroupId;
}

/// <summary>
/// Constructs and returns <c>METStockReservation</c>.
/// </summary>
/// <param name = "_salesTable">
/// <c>SalesTable</c>.
/// </param>
/// <returns>
///  <c>METStockReservation</c>.
/// </returns>
public static METStockReservation construct(SalesTable _salesTable)
{
    METStockReservation stockReservation;

    stockReservation = new METStockReservation();

    stockReservation.parmSalesTable(_salesTable);
    stockReservation.init();

    return stockReservation;
}

/// <summary>
/// Initializes the class variables.
/// </summary>
private void init()
{
    metCustParameters = METCustParameters::Find();
    inventParameter = InventParameters::find();

    //CB238 - xDock process
    METSalesTable metSalesTable;
    InventLocation inventLocation;

    select firstonly InternalCrossDockOrder from metSalesTable
        where metSalesTable.SalesTable == salesTable.RecId;

    select firstonly METCSDWarehouse from inventLocation
        where inventLocation.InventLocationId == salesTable.InventLocationId;

    isCrossDockOrCSDOrder = metSalesTable.InternalCrossDockOrder == NoYes::Yes || inventLocation.METCSDWarehouse == NoYes::Yes;

    isIntercompanyTransferFulfillment = salesTable.METIntercompanyTransferFulfillment;
    batchTransactionCommit = metCustParameters.SalesExtractionBatchTransactionCommit;
}

public void processCrossDockCSDOrder()
{
    ttsbegin;
    this.reserveStock();
    this.endProcess();
    ttscommit;
}

/// <summary>
/// CB167_PerformStockReservation
/// Executes the stock reservation process.
/// </summary>
public void process()
{

    try
    {
        procMetrics = METProcMetricsScope::current();

        //Reserves stock.
        this.reserveStock();

        //CB238 - if the sales order is an internal cross dock order or the warehouse is a CSD warehouse
        //then do not perform substitution, the substitution will be performed during transfer order extraction.
        if(!isCrossDockOrCSDOrder
            && !isIntercompanyTransferFulfillment)
        {
            //Optimises sales order.
            this.optimiseSalesOrder();

            if (lineSubstituted)
            {
                //Re-reserves after sales order optimization.
                this.reserveStock();
            }
        }
        else
        {
            //if the Sales order is internal cross dock order and the parameter reserve item automatically is enabled, then attempt reservation .
            if(inventParameter.InventTransferAutoReservation == NoYes::Yes
                && !isIntercompanyTransferFulfillment)
            {
                //Optimises sales order.
                this.optimiseSalesOrder();

                if (lineSubstituted)
                {
                    //Re-reserves after sales order optimization.
                    this.reserveStock();
                }
            }

        }
        //Ends process update
        this.endProcess();

        Info("@MET:StockReserved");
    }
    catch
    {  
        warning("@MET:METStockReservationError");
    }

}

