/// <summary>
/// CB167_PerformStockReservation
/// Reserves stock against the sales order.
/// </summary>
private void reserveStock()
{
    this.reserve();
}

/// <summary>
/// CB167_PerformStockReservation
/// Reserves stock against the sales order.
/// </summary>
private void reserveStockV2()
{
    this.reserveV2();
}

/// <summary>
/// CB167_PerformStockReservation
/// Optimises sales order.
/// </summary>
private void optimiseSalesOrder()
{
    ttsbegin;
    this.substituteSalesLine();
    ttscommit;
}

/// <summary>
/// CB167_PerformStockReservation
/// Reserves quantity against sales lines.
/// </summary>
private void reserve()
{
    SalesLine             salesLine;
    METSalesLine          metSalesLine;
    InventTrans           inventTrans;
    InventTransOrigin     inventTransOrigin;
    InventMovement        inventMovement;
    InventQty             reserveQty;
    InventUpd_Reservation reservation;
    int                   batchCount;
    boolean               batchOpen;

    while select ItemId, InventDimId, QtyOrdered, InventTransId from salesLine
            where salesLine.SalesId     == salesTable.SalesId
            &&  salesLine.SalesStatus == SalesStatus::Backorder
        join inventTrans
            where inventTrans.StatusIssue == StatusIssue::OnOrder
        join RecId from inventTransOrigin
            where inventTransOrigin.RecId == inventTrans.InventTransOrigin
            &&    inventTransOrigin.InventTransId == salesLine.InventTransId
        exists join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
            &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
            &&     metSalesLine.ReasonId  != METConstants::NewReasonCode)
    {
        if (!batchOpen)
        {
            this.ttsBeginTrace();
            batchOpen = true;
        }

        reserveQty = inventTrans.Qty;

        if (this.checkIfQtyAvailableForReservation(salesLine))
        {
            inventMovement = inventTrans.inventMovement(true);
            reservation    = InventUpd_Reservation::newMovement(inventMovement, reserveQty, true);
            reservation.updateNow();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(3, 1);
            }
        }

        batchCount++;

        if (batchCount >= batchTransactionCommit)
        {
            this.ttsCommitTrace();
            batchOpen = false;
            batchCount = 0;
        }
    }

    if (batchOpen)
    {
        this.ttsCommitTrace();
    }
}

/// <summary>
/// CB167_PerformStockReservation
/// Reserves quantity against sales lines.
/// </summary>
private void reserveV2()
{
    SalesLine                salesLine;
    METSalesLine             metSalesLine;
    InventTrans              inventTrans;
    InventTransOrigin        inventTransOrigin;
    InventDim                inventDim;
    InventMovement           inventMovement;
    InventUpd_WHSReservation whsReservation;
    InventSum                availSum;
    InventDim                whsCheckDim;
    int                      batchCount;
    boolean                  batchOpen;

    while select salesLine
            where salesLine.SalesId     == salesTable.SalesId
            &&  salesLine.SalesStatus == SalesStatus::Backorder
        join inventDim
            where inventDim.InventDimId == salesLine.InventDimId
        join inventTrans
            where inventTrans.StatusIssue == StatusIssue::OnOrder
        join RecId from inventTransOrigin
            where inventTransOrigin.RecId == inventTrans.InventTransOrigin
            &&    inventTransOrigin.InventTransId == salesLine.InventTransId
        exists join metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
            &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
            &&     metSalesLine.ReasonId  != METConstants::NewReasonCode)
    {
        if (!batchOpen)
        {
            this.ttsBeginTrace();
            batchOpen = true;
        }

        if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
        {
            select sum(AvailPhysical), sum(pdsCWAvailPhysical) from availSum
              exists join whsCheckDim
                  where whsCheckDim.inventDimId      == availSum.inventDimId
                  &&    whsCheckDim.InventSiteId     == inventDim.InventSiteId
                  &&    whsCheckDim.InventLocationId == inventDim.InventLocationId
                  &&    availSum.ItemId              == salesLine.ItemId;

            if (availSum.pdsCWAvailPhysical > 0)
            {
                InventQty      reserveQty   = -min(abs(inventTrans.Qty),      availSum.AvailPhysical);
                PdsCWInventQty reserveCWQty = -min(abs(inventTrans.PdsCWQty), availSum.pdsCWAvailPhysical);

                inventMovement = inventMovement::constructNoThrow(salesLine);
                whsReservation = InventUpd_Reservation::newMovement(inventMovement, reserveQty, true, false, false, reserveCWQty);
                whsReservation.parmPdsCWForceActual(true);
                whsReservation.updateNow();

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(3, 1);
                }
            }
        }
        else
        {
            inventMovement = inventMovement::constructNoThrow(salesLine);
            whsReservation = InventUpd_Reservation::newMovement(inventMovement, inventTrans.Qty, true);
            whsReservation.updateNow();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(3, 1);
            }
        }

        batchCount++;

        if (batchCount >= batchTransactionCommit)
        {
            this.ttsCommitTrace(3);
            batchOpen = false;
            batchCount = 0;
        }
    }

    if (batchOpen)
    {
        this.ttsCommitTrace(3);
    }
}

/// <summary>
/// CB167_PerformStockReservation/
/// Substitutes sales lines.
/// </summary>
private void substituteSalesLine()
{
    METSubstitutionSalesLineProcess subSalesLineProcess;
    SalesLine                       salesLine;
    METSalesLine                    metSalesLine;
    InventTransOrigin               inventTransOrigin;
    InventTrans                     inventTrans, inventTransReserved;

    while select salesLine
        where salesLine.SalesId     == salesTable.SalesId
        &&    salesLine.SalesStatus == SalesStatus::Backorder
     join RecId from  metSalesLine
        where metSalesLine.SalesLine == salesLine.RecId
        &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
        &&     metSalesLine.ReasonId  != METConstants::NewReasonCode)
    join InventTransId, RecId from inventTransOrigin
        where inventTransOrigin.InventTransId == salesLine.InventTransId
    exists join RecId from inventTrans
        where inventTrans.StatusIssue == StatusIssue::OnOrder &&
        inventTrans.InventTransOrigin == inventTransOrigin.RecId    
    notexists join RecId from inventTransReserved
        where inventTransReserved.StatusIssue == StatusIssue::ReservPhysical &&
        inventTransReserved.InventTransOrigin == inventTransOrigin.RecId
    {
        // Bug 251684: CB166 - Subs on extraction where have OOS then Never not being applied
        // Old method was considering "reserved ordered" which happens when counting journal not posted creates available for reservation stock
        // New method will look at "reserved physical" only
        //if (!salesLine.reservedPhysicalInSalesUnit())
        //{
            //CB238 - xDock If the order is cross dock, then attempt substitution on NDC warehouse.
            // Bug 225259: CB238 - NDC / Int xDock: D365 functional warehouse processing Liquor LE SO extraction and TO extraction LSE004 and LTE003 substitution issues
            // Adding local WH inventory dimension for stock on hand
            // Note the first substitute is called for xDock and non xDock scenarios
            subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLine, salesLine.inventDim());

            if (subSalesLineProcess.run() && !lineSubstituted)
            {
                lineSubstituted = true;
            }
            // Bug 225259: CB238 - NDC / Int xDock: D365 functional warehouse processing Liquor LE SO extraction and TO extraction LSE004 and LTE003 substitution issues
            // if no substitution done in local WH, try substitution with supplying WH
            else if (isCrossDockOrCSDOrder)
            {
                subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLine, salesLine.metInventDimSupplyingWarehouse());
                if (subSalesLineProcess.run() && !lineSubstituted)
                {
                    lineSubstituted = true;
                }
            }
        //}
    }
}

/// <summary>
/// Processing at the end.
/// </summary>
private void endProcess()
{
    if (lineSubstituted)
    {
        ttsbegin;

        METSalesTable metSalesTable = METSalesTable::findByRefRecId(salesTable.RecId, true);
        if (metSalesTable)
        {
            metSalesTable.OrderProcessingStatus = METSalesOrderProcessingStatus::ReadyForPricing;
            metSalesTable.update();
        }


        // Step 4: Call TMS engine
        METTMSEngineOrderProccess  METTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderCreation, salesTable);
        METTMSEngineOrderProccess.run();
        ttscommit;
    }
}

private void endProcessForLines()
{
    if (lineSubstituted)
    {
        METSalesOrderExtractionLine extractionLine;

        ttsbegin;

        update_recordset extractionLine
            setting LineSubstituted = NoYes::Yes
            where extractionLine.SalesId == salesTable.SalesId
            && extractionLine.ExtractionId == extractionId
            && extractionLine.LineSubstituted == NoYes::No;

        ttscommit;
    }
}

/// <summary>
/// Checks if quantity is available for reservation.
/// </summary>
/// <param name = "_salesLine"> SalesLine reference </param>
/// <returns>Boolean value</returns>
public boolean checkIfQtyAvailableForReservation(SalesLine  _salesLine)
{
    InventDim       inventDimOnHand;
    InventDimParm   inventDimParm;
    Qty             availPhysical;
    Qty             availPhysicalCW;

    boolean         ret = false;

    inventDimOnHand.clear();
    inventDimOnHand.initFromInventDim(_salesLine.inventDim());

    inventDimParm.clear();
    inventDimParm.initFromInventDim(inventDimOnHand);

    InventOnHand onHand = InventOnHand::newParameters(_salesLine.ItemId, _salesLine.inventDim(),inventDimParm);

    availPhysical   = onHand.availPhysical();

    if (PdsGlobal::pdsIsCWItem(_salesLine.ItemId)) // For CW items, both physical and CW availability should be checked. there was a case where physical availability was greater than 0 but CW availability was 0, which caused reservation to fail and substitution to be skipped, even though there was available stock that could be reserved.
    {
        availPhysicalCW = onHand.pdsCWAvailPhysical();
        ret = availPhysical > 0 && availPhysicalCW > 0;
    }
    else
    {
        ret = availPhysical > 0;
    }

    return ret;
}

public void ttsBeginTrace()
{
    if (procMetrics)
    {
        procMetrics.ttsBeginTrace();
    }
    else
    {
        ttsbegin;
    }
}

public void ttsCommitTrace(int _slot = 0)
{
    if (procMetrics)
    {
        if (_slot > 1)
        {
            procMetrics.startDualWriteTime(_slot);
        }

        procMetrics.ttsCommitTrace();

        if (_slot > 1)
        {
            procMetrics.endDualWriteTime(_slot);
        }
    }
    else
    {
        ttscommit;
    }
}

public void processV2ForLines(container _salesLineRecIdList, METSalesOrderExtractionId _extractionId = '')
{
    try
    {
        extractionId = _extractionId;
        procMetrics = METProcMetricsScope::current();

        //Reserves stock.
        this.reserveStockV2ForLines(_salesLineRecIdList);

        //CB238 - if the sales order is an internal cross dock order or the warehouse is a CSD warehouse
        //then do not perform substitution, the substitution will be performed during transfer order extraction.
        if(!isCrossDockOrCSDOrder
            && !isIntercompanyTransferFulfillment)
        {
            //Optimises sales order.
            this.optimiseSalesOrderForLines(_salesLineRecIdList);

            if (lineSubstituted)
            {
                //Re-reserves after sales order optimization.
                this.reserveStockV2ForLines(_salesLineRecIdList);
            }
        }
        else
        {
            //if the Sales order is internal cross dock order and the parameter reserve item automatically is enabled, then attempt reservation .
            if(inventParameter.InventTransferAutoReservation == NoYes::Yes
                && !isIntercompanyTransferFulfillment)
            {
                //Optimises sales order.
                this.optimiseSalesOrderForLines(_salesLineRecIdList);

                if (lineSubstituted)
                {
                    //Re-reserves after sales order optimization.
                    this.reserveStockV2ForLines(_salesLineRecIdList);
                }
            }

        }
        //Ends process update
        this.endProcessForLines();

        Info("@MET:StockReserved");
    }
    catch
    {
        warning("@MET:METStockReservationError");
    }
}

private void reserveStockV2ForLines(container _salesLineRecIdList)
{
    this.reserveV2ForLines(_salesLineRecIdList);
}

private void reserveV2ForLines(container _salesLineRecIdList)
{
    SalesLine                salesLine;
    METSalesLine             metSalesLine;
    InventTrans              inventTrans;
    InventTransOrigin        inventTransOrigin;
    InventDim                inventDim;
    InventMovement           inventMovement;
    InventUpd_WHSReservation whsReservation;
    InventSum                availSum;
    InventDim                whsCheckDim;
    int                      batchCount;
    boolean                  batchOpen;
    int                      i;

    for (i = 1; i <= conLen(_salesLineRecIdList); i++)
    {
        RefRecId lineRecId = conPeek(_salesLineRecIdList, i);

        select firstonly salesLine
                where salesLine.RecId       == lineRecId
                &&    salesLine.SalesId     == salesTable.SalesId
                &&    salesLine.SalesStatus == SalesStatus::Backorder
            join inventDim
                where inventDim.InventDimId == salesLine.InventDimId
            join inventTrans
                where inventTrans.StatusIssue == StatusIssue::OnOrder
            join RecId from inventTransOrigin
                where inventTransOrigin.RecId == inventTrans.InventTransOrigin
                &&    inventTransOrigin.InventTransId == salesLine.InventTransId
            exists join metSalesLine
                where metSalesLine.SalesLine == salesLine.RecId
                &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
                &&     metSalesLine.ReasonId  != METConstants::NewReasonCode);

        if (!salesLine.RecId)
        {
            continue;
        }

        if (!batchOpen)
        {
            this.ttsBeginTrace();
            batchOpen = true;
        }

        if (PdsGlobal::pdsIsCWItem(salesLine.ItemId))
        {
            select sum(AvailPhysical), sum(pdsCWAvailPhysical) from availSum
              exists join whsCheckDim
                  where whsCheckDim.inventDimId      == availSum.inventDimId
                  &&    whsCheckDim.InventSiteId     == inventDim.InventSiteId
                  &&    whsCheckDim.InventLocationId == inventDim.InventLocationId
                  &&    availSum.ItemId              == salesLine.ItemId;

            if (availSum.pdsCWAvailPhysical > 0)
            {
                InventQty      reserveQty   = -min(abs(inventTrans.Qty),      availSum.AvailPhysical);
                PdsCWInventQty reserveCWQty = -min(abs(inventTrans.PdsCWQty), availSum.pdsCWAvailPhysical);

                inventMovement = inventMovement::constructNoThrow(salesLine);
                whsReservation = InventUpd_Reservation::newMovement(inventMovement, reserveQty, true, false, false, reserveCWQty);
                whsReservation.parmPdsCWForceActual(true);
                whsReservation.updateNow();

                if (procMetrics)
                {
                    procMetrics.incDescriptionCount(3, 1);
                }
            }
        }
        else
        {
            inventMovement = inventMovement::constructNoThrow(salesLine);
            whsReservation = InventUpd_Reservation::newMovement(inventMovement, inventTrans.Qty, true);
            whsReservation.updateNow();

            if (procMetrics)
            {
                procMetrics.incDescriptionCount(3, 1);
            }
        }

        batchCount++;

        if (batchCount >= batchTransactionCommit)
        {
            this.ttsCommitTrace(3);
            batchOpen = false;
            batchCount = 0;
        }
    }

    if (batchOpen)
    {
        this.ttsCommitTrace(3);
    }
}

private void optimiseSalesOrderForLines(container _salesLineRecIdList)
{
    ttsbegin;
    this.substituteSalesLineForLines(_salesLineRecIdList);
    ttscommit;
}

private void substituteSalesLineForLines(container _salesLineRecIdList)
{
    METSubstitutionSalesLineProcess subSalesLineProcess;
    SalesLine                       salesLine;
    METSalesLine                    metSalesLine;
    InventTransOrigin               inventTransOrigin;
    InventTrans                     inventTrans, inventTransReserved;
    int                              i;

    for (i = 1; i <= conLen(_salesLineRecIdList); i++)
    {
        RefRecId lineRecId = conPeek(_salesLineRecIdList, i);

        select firstonly salesLine
            where salesLine.RecId       == lineRecId
            &&    salesLine.SalesId     == salesTable.SalesId
            &&    salesLine.SalesStatus == SalesStatus::Backorder
         join RecId from  metSalesLine
            where metSalesLine.SalesLine == salesLine.RecId
            &&    (metSalesLine.ReasonId  != METConstants::NIRReasonCode
            &&     metSalesLine.ReasonId  != METConstants::NewReasonCode)
        join InventTransId, RecId from inventTransOrigin
            where inventTransOrigin.InventTransId == salesLine.InventTransId
        exists join RecId from inventTrans
            where inventTrans.StatusIssue == StatusIssue::OnOrder &&
            inventTrans.InventTransOrigin == inventTransOrigin.RecId
        notexists join RecId from inventTransReserved
            where inventTransReserved.StatusIssue == StatusIssue::ReservPhysical &&
            inventTransReserved.InventTransOrigin == inventTransOrigin.RecId;

        if (!salesLine.RecId)
        {
            continue;
        }

        subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLine, salesLine.inventDim());

        if (subSalesLineProcess.run() && !lineSubstituted)
        {
            lineSubstituted = true;
        }
        else if (isCrossDockOrCSDOrder)
        {
            subSalesLineProcess = METSubstitutionSalesLineProcess::construct(salesLine, salesLine.metInventDimSupplyingWarehouse());
            if (subSalesLineProcess.run() && !lineSubstituted)
            {
                lineSubstituted = true;
            }
        }
    }
}
